WITH valid AS (SELECT *, COALESCE(browser, 'Unknown') AS browser_filled, HOUR(started_at) AS started_at_hour, COALESCE(browser, 'N/A') AS resolved_browser FROM sessions WHERE started_at >= TIMESTAMP '2023-11-29 23:00:00') SELECT * FROM (SELECT browser, device, started_at_hour FROM valid) src PIVOT (MAX(started_at_hour) AS total, COUNT(1) AS n FOR device IN ('mobile', 'desktop', 'tablet'));
